/* Application features and authenticated API adapter. Demo data never migrates into real accounts. */
const demoRender=render,demoHome=home,demoFarmer=farmer;let authResolved=false,account=null,cloud=null,viewFilter='all';
state.records??=[];state.preferences??={name:'Павел',goal:20};
const pendingReads=new Map();
const api=async(path,body)=>{
 const identity=account?.id||'guest';const key=identity+':'+path;
 if(body===undefined&&pendingReads.has(key))return pendingReads.get(key);
 const run=async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json'},credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});let d;try{d=await r.json()}catch{throw Error('Сервер пока недоступен. Попробуйте ещё раз.')}if(!r.ok)throw Error(d.error||'Ошибка сервера');if(path!=='me'&&path!=='login'&&path!=='register'&&(account?.id||'guest')!==identity)throw Error('Аккаунт изменился. Откройте экран заново.');return d}catch(e){if(e.name==='AbortError')throw Error('Ответ задерживается. Результат пока неизвестен: проверьте список задач перед повторной оплатой.');if(e instanceof TypeError)throw Error('Не удалось связаться с сервером. Проверьте интернет. Если вы подтверждали оплату, сначала проверьте список задач.');throw e}finally{clearTimeout(timer)}};
 const promise=run();if(body!==undefined)return promise;pendingReads.set(key,promise);try{return await promise}finally{if(pendingReads.get(key)===promise)pendingReads.delete(key)}
};
const formAsync=(title,fields,handler)=>{modalForm(title,fields,()=>{});const form=$('#form');const error=document.createElement('div');error.className='form-error';error.setAttribute('role','alert');error.setAttribute('tabindex','-1');error.hidden=true;$('#fields').prepend(error);let pending=false;form.onsubmit=async e=>{e.preventDefault();if(pending)return;pending=true;const btn=e.submitter;error.hidden=true;error.textContent='';if(btn)btn.disabled=true;form.setAttribute('aria-busy','true');try{await handler(new FormData(e.target));modal.close();render()}catch(err){toast(err?.message||'Не удалось выполнить действие. Попробуйте ещё раз.');}finally{pending=false;if(btn)btn.disabled=false;form.removeAttribute('aria-busy')}}};
function profile(){if(!account)return authDialog('login');formAsync('Ваш аккаунт',`<p>${esc(account.name)} · ${esc(account.login)}</p><p class="note">Роль: ${esc(account.role)}</p><button class="btn">Выйти из аккаунта</button>`,async()=>{await api('logout',{});location.reload()})}

async function refreshCloud(){cloud=await api('state');account=cloud.user;render()}
function myPlots(){return account?cloud.plots.filter(p=>p.mine):state.plots}
function records(kind){return account?(cloud?.records||[]).filter(r=>r.kind===kind).map(r=>({id:r.id,plot:r.plot_id,...r.data})):state.records.filter(r=>r.kind===kind)}
const routeTitles={planner:'План посадок',journal:'Дневник',harvest:'Мой урожай',delivery:'Доставка',guide:'Агро-помощник',settings:'Настройки'};
const extraNav=document.createElement('div');extraNav.className='more-nav';extraNav.innerHTML=Object.entries(routeTitles).map(([k,v])=>`<a href="#${k}">${v}</a>`).join('');document.querySelector('nav').append(extraNav);
const userButton=document.createElement('button');userButton.className='btn light account-button';userButton.textContent='Войти / регистрация';userButton.onclick=profile;document.querySelector('header').append(userButton);
const statusBanner=document.querySelector('.demobar');
function plotOptions(){return myPlots().map(p=>`<option value="${p.id}">№${p.id} · ${esc(p.name)}</option>`).join('')}
function recordForm(kind){const labels={planting:'Запланировать посадку',note:'Записать наблюдение',harvest:'Записать урожай',delivery:'Запланировать получение',task:'Новое задание',listing:'Предложить товар'};formAsync(labels[kind],`<label>Название<input name="title" required maxlength="120" placeholder="${kind==='planting'?'Например, базилик зелёный':'Что запишем?'}"></label><label>Грядка<select name="plot"><option value="">Без привязки</option>${plotOptions()}</select></label><label>Дата<input type="date" name="date" required value="${new Date().toLocaleDateString('en-CA')}"></label>${['harvest','listing'].includes(kind)?'<label>Количество / цена<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required></label>':''}<label>Описание<input name="description" maxlength="600" placeholder="Сорт, уход, вес, способ получения…"></label><p class="note">${kind==='delivery'?'Это план получения урожая. Курьер и адрес доставки пока не согласованы.':account?'Запись сохраняется в твоём аккаунте.':'Деморежим: запись остаётся в этом браузере.'}</p><button class="btn">Сохранить</button>`,async f=>{const d={...Object.fromEntries(f),kind};if(account)await api('record',d);else{state.records.push({...d,id:crypto.randomUUID(),status:'saved'});save()}if(account)await refreshCloud();toast('Запись сохранена')})}
function recordCards(kind){const list=records(kind);return list.length?list.map(r=>`<article class="panel"><div class="row"><small>${esc(r.date||'Без даты')}</small><span class="pill">${r.plot?'Грядка №'+r.plot:'Хозяйство'}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.description||'Описание не добавлено')}</p>${r.amount?`<strong>${Number(r.amount)} ${kind==='harvest'?'кг':'₽'}</strong>`:''}</article>`).join(''):'<div class="empty panel"><span>✳</span><h3>Здесь начинается история твоего хозяйства</h3><p>Добавь первую запись. Она появится в этом разделе.</p></div>'}
function planner(){return heading('У каждого сезона — свой план.','Посадки, даты и заметки по каждой грядке.','<button class="btn" onclick="recordForm(\'planting\')">＋ Запланировать</button>')+`<div class="season-strip"><span>01 · Выбери культуру</span><span>02 · Назначь грядку</span><span>03 · Следи за ростом</span><span>04 · Собери своё</span></div><div class="grid">${recordCards('planting')}</div><div class="panel promo" style="margin-top:22px"><h3>Сезон начинается с условий</h3><p>Сроки посева зависят от региона, теплицы и сорта. Согласуй план с фермером перед посадкой.</p><a href="#guide" class="btn light">Открыть помощника</a></div>`}
function journal(){return heading('Ничего важного не потеряется.','Наблюдения, маленькие открытия и история твоих грядок.','<button class="btn" onclick="recordForm(\'note\')">＋ Наблюдение</button>')+`<div class="grid">${recordCards('note')}</div>`}
function harvest(){let total=records('harvest').reduce((s,r)=>s+Number(r.amount||0),0);return heading('Самое приятное — собирать.','Учитывай урожай и планируй, что окажется на столе.','<button class="btn" onclick="recordForm(\'harvest\')">＋ Записать урожай</button>')+`<div class="stats"><div class="stat"><small>СОБРАНО</small><strong>${total.toFixed(1)} кг</strong></div><div class="stat"><small>СБОРОВ</small><strong>${records('harvest').length}</strong></div><div class="stat"><small>МОЯ ЦЕЛЬ</small><strong>${state.preferences.goal} кг</strong></div><div class="stat"><small>ПРОГРЕСС</small><strong>${Math.min(100,Math.round(total/state.preferences.goal*100))}%</strong></div></div><div class="grid">${recordCards('harvest')}</div>`}
function delivery(){return heading('С грядки — к твоему столу.','Планируй самовывоз или обсуждение доставки с фермером.','<button class="btn" onclick="recordForm(\'delivery\')">＋ План получения</button>')+`<p class="note">Записи не вызывают курьера. Логистическая служба и оплата доставки ещё не подключены.</p><div class="grid">${recordCards('delivery')}</div>`}
const crops=[['🍅','Томаты','Опора, равномерная влажность и регулярный осмотр листьев.','Не назначай подкормки без согласования с фермером.'],['🥬','Листовые салаты','Нежные листья, небольшие порции и последовательные посадки.','Перед сбором проверь сроки и состояние растений.'],['🥕','Морковь','Рыхлая почва, аккуратное прореживание и терпение.','Сорт и условия определяют время сбора.'],['🌿','Пряные травы','Небольшая грядка для свежей зелени к столу.','У разных трав отличаются требования к поливу.'],['🍓','Клубника','Мульча, наблюдение за ягодами и своевременный сбор.','Не обещаем урожай вне сезона без подходящих условий.'],['🥒','Огурцы','Опора, тепло и регулярный сбор созревших плодов.','При похолодании обсуди защиту растений.']];
function guide(){return heading('Чуть больше понимания.','Короткие ориентиры для разговора с фермером.')+`<div class="grid marketgrid">${crops.map(c=>`<article class="panel"><div class="cropicon">${c[0]}</div><h3>${c[1]}</h3><p>${c[2]}</p><small>${c[3]}</small><p><button class="btn light" onclick="recordForm('planting')">В план посадок</button></p></article>`).join('')}</div>`}
function settings(){return heading('Хозяйство с твоим характером.','Настройки устройства и личные ориентиры.')+`<div class="grid"><section class="panel"><h3>Цель сезона</h3><p>Сколько килограммов хочешь собрать?</p><form onsubmit="event.preventDefault();state.preferences.goal=Number(this.goal.value);save();toast('Цель сохранена')"><input name="goal" aria-label="Цель урожая в килограммах" type="number" min="1" max="10000" value="${state.preferences.goal}"><button class="btn">Сохранить</button></form></section><section class="panel"><h3>Твоё приложение</h3><p>Открой меню браузера и выбери «Добавить на главный экран», если браузер поддерживает эту функцию.</p><p class="note">Для работы с аккаунтом и актуальными данными нужен интернет.</p><button class="btn light" onclick="exportData()">Экспортировать мои записи</button></section></div>`}
function exportData(){const content=JSON.stringify(account?{plots:myPlots(),records:cloud.records.filter(r=>r.owner_id===account.id)}:state,null,2),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'application/json'}));a.download='farm-off-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
rent=function(){return heading('Моё хозяйство','')+'<p>Загружаем доступные грядки…</p>'};
const demoLease=lease,demoCare=care,demoSign=sign,demoCamera=camera;
lease=function(id){if(!account){profile();return}const p=cloud.plots.find(p=>p.id===id),key=crypto.randomUUID();if(!p?.rental_monthly_kopecks){toast('Тариф участка ещё не настроен');return}formAsync('Арендовать грядку №'+id,`<h3>${p.size} м² · ${money(p.rental_monthly_kopecks)} / месяц</h3><label>Срок<select name="months" onchange="document.getElementById('rental-total').textContent=money(${p.rental_monthly_kopecks}*Number(this.value))">${[1,2,3,6,12].map(n=>`<option value="${n}">${n} мес.</option>`).join('')}</select></label><p>Итого: <strong id="rental-total">${money(p.rental_monthly_kopecks)}</strong></p><p class="note">Демоаренда, списание только тестовых средств. Уход и материалы отдельно. Физический участок требует подтверждения фермы. Автопродления нет.</p><a href="#wallet" onclick="modal.close()">Пополнить демобаланс</a><button class="btn">Оплатить демобалансом и арендовать</button>`,async f=>{await api('claim',{id,months:Number(f.get('months')),key});await refreshCloud();location.hash='home';toast('Грядка появилась в хозяйстве')})};
care=function(id){if(!account)return demoCare(id);recordForm('task');const select=$('#form select[name="plot"]');if(select)select.value=String(id)};
sign=function(id){if(!account)return demoSign(id);const p=cloud.plots.find(p=>p.id===id);formAsync('Моя грядка',`<label>Название<input name="name" required maxlength="60" value="${esc(p.name)}"></label><label>Культура<input name="crop" maxlength="60" value="${esc(p.crop)}"></label><label>Табличка<input name="sign" maxlength="40" value="${esc(p.sign)}"></label><button class="btn">Сохранить</button>`,async f=>{await api('plot',{...Object.fromEntries(f),id,version:p.version});await refreshCloud()})};
camera=async function(id){if(!account)return demoCamera(id);try{const d=await api('camera?id='+id);modalForm('Камера · №'+id,d.url?'<video id="stream" controls playsinline></video><p class="note">Воспроизведение зависит от формата потока и браузера.</p>':'<div class="empty"><span>◎</span><h3>Камера пока не подключена</h3><p>Фермер добавит адрес трансляции после установки оборудования.</p></div>',()=>{});if(d.url){$('#stream').src=d.url;$('#stream').onerror=()=>toast('Браузер не смог воспроизвести поток. Проверь формат камеры.')}}catch(e){toast(e.message)}};
function cloudHome(){return heading('Твоё хозяйство, '+esc(account.name)+'.','Настоящие записи. Твои участки. Всё в одном месте.','<a class="btn" href="#rent">＋ Добавить грядку</a>')+`<section class="hero"><span class="eyebrow">ФЕРМА ОФФЛАЙН · ТЫ НА СВЯЗИ</span><h2>Пусть растёт то,<br>что важно тебе.</h2><p>Планируй посадки, наблюдай, общайся через задания.</p><a href="#planner" class="btn">Мой план посадок ↗</a></section><div class="quick-actions"><a href="#planner">♧ План посадок</a><a href="#journal">☷ Дневник</a><a href="#harvest">◈ Урожай</a><a href="#delivery">↗ Получение</a></div><div class="sectiontitle"><h2>Мои грядки · ${myPlots().length}</h2></div><div class="grid">${myPlots().length?myPlots().map((p,i)=>`<article class="card"><div class="plot-art"><span>♧</span><b>№${p.id}</b><div class="tag">${esc(p.sign||'Твоя табличка')}</div></div><div class="cardbody"><h3>${esc(p.name)}</h3><p>${esc(p.crop||'Культура ещё не выбрана')} · ${p.size} м²</p><div class="actions"><button class="btn" onclick="camera(${p.id})">Камера</button><button class="btn light" onclick="care(${p.id})">Задание</button><button class="btn light" onclick="sign(${p.id})">Настроить</button></div></div></article>`).join(''):'<section class="panel empty"><h3>Первый шаг — своя грядка</h3><p>Посмотри доступные участки на карте фермы.</p><a class="btn" href="#rent">Выбрать участок</a></section>'}</div>`}
function cloudFarmer(){if(!['admin','farmer'].includes(account.role))return heading('Кабинет фермера','Доступен сотрудникам фермы.')+'<section class="panel"><p>Твой аккаунт имеет роль пользователя. Роль фермера назначает администратор на сервере.</p></section>';return heading('Вся ферма — перед глазами.','Участки, камеры и очередь работ.')+`<div class="grid"><section class="panel"><h3>Задания</h3>${records('task').map(t=>`<div class="event"><p>№${t.plot||'—'} · ${esc(t.title)}</p><small>${esc(t.description||'')}</small><p><button class="btn light" ${t.status==='done'?'disabled':''} onclick="completeTask('${t.id}')">${t.status==='done'?'Выполнено':'Завершить'}</button></p></div>`).join('')||'<p>Новых заданий нет.</p>'}</section><section class="panel"><h3>Готовность участков</h3>${cloud.plots.map(p=>`<div class="event row"><span>№${p.id} · ${esc(p.status)}</span><button class="btn light" onclick="configurePlot(${p.id})">Настроить</button></div>`).join('')}</section></div>`}
async function completeTask(id){try{await api('complete-task',{id});await refreshCloud()}catch(e){toast(e.message)}}
function configurePlot(id){formAsync('Подключение участка №'+id,'<label>Готовность<select name="available"><option value="false">Закрыт для бронирования</option><option value="true">Готов к бронированию</option></select></label><label>HTTPS-адрес камеры<input name="camera" type="url" placeholder="https://…"></label><p class="note">Только поток без пароля в URL. Пустое поле отключит камеру. Для приватных камер нужен шлюз с авторизацией.</p><button class="btn">Сохранить</button>',async f=>{await api('configure-plot',{id,available:f.get('available')==='true',camera:f.get('camera')});await refreshCloud()})}
const oldSell=sell;
sell=function(){if(account)return recordForm('listing');oldSell()};
render=function(){const route=location.hash.slice(1)||'home';const custom={planner,journal,harvest,delivery,guide,settings};if(custom[route]){$('#app').innerHTML=custom[route]();$('#crumb').textContent=routeTitles[route].toUpperCase()}else if(account&&route==='home')$('#app').innerHTML=cloudHome();else if(account&&route==='farmer')$('#app').innerHTML=cloudFarmer();else if(account&&route==='market'){$('#app').innerHTML=heading('Маркет фермы','Объявления пользователей. Покупка и оплата согласуются отдельно.','<button class="btn" onclick="sell()">＋ Объявление</button>')+`<div class="grid">${recordCards('listing')}</div>`}else demoRender();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));userButton.textContent=account?account.name:'Войти / регистрация';document.querySelector('header>span:nth-child(2)').textContent=account?'Датчики не подключены':'☀ +24° · пример';statusBanner.textContent=account?'Личный кабинет · данные на сервере · камеры и участки подключает фермер':'Деморежим · попробуй возможности или войди для работы с реальными данными';if(!account&&route==='home'){$('#app').insertAdjacentHTML('beforeend','<div class="quick-actions"><a href="#planner">♧ План посадок</a><a href="#journal">☷ Дневник</a><a href="#harvest">◈ Урожай</a><a href="#guide">✳ Помощник</a></div>')}};
render();api('me').then(async d=>{if(d.user)await refreshCloud()}).catch(e=>toast(e.message)).finally(()=>{authResolved=true;render()});
